  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (246, 5, $p3b_246$[{"t": "list", "id": "s1-2-4-b1", "imp": "core", "items": ["1、==表达式：运算对象加运算符构成表达式==例如：赋值运算符加运算对象构成赋值表达式；i+=1", "2、==表达式语句：表达式加分号构成表达式语句==例如：赋值表达式加分号又可构成赋值语句；i+=1;", "3、==运算对象：运算对象可以是==@@表达式、常量、变量@@例如：", "表达式：a+b,a+a,a>b;", "常量：100L、3.1415F;", "变量：a,b,c,i,j；", "4、C 语言表达式类型：==算术表达式、关系表达式、逻辑表达式、条件表达式、赋值表达式、逗号表达式、其他表达式（按位运算表达式、复合表达式等）==。"], "title": "", "ordered": false}, {"h": 413, "t": "img", "w": 923, "id": "s1-2-4-b2", "alt": "表达式与运算符结合构成算术、关系、逻辑等 C 语言合法表达式导图", "imp": "normal", "src": "/kb-assets/skill/p23_r0_62ae22090b64dd2f.png", "title": "", "caption": "常量/变量与运算符组成常见 C 语言表达式类型体系（算术/关系/逻辑/条件/赋值/逗号表达式）"}, {"t": "list", "id": "s1-2-4-b3", "imp": "core", "items": ["5、算术表达式", "（1）运算对象加算术运算符(==+-*/%==)", "（2）算术表达式加分号构成算术表达式语句。", "（3）==求余（%）运算要求运算对象只能为整型==。", "（4）==除法（/）运算符两边运算对象都为整型时，运算结果也为整型即舍掉小数部分。==", "（5）注意优先级，类型转换（隐式与显示），常考点：", "（3）和（4）", "6、关系表达式", "（1）运算对象加关系运算符（==>,<,>=,<=,!=,`==`==）", "（2）关系表达式加分号构成关系表达式语句。", "（3）==C 语言用非0 表示逻辑真（值为1），用0 表示逻辑假（值为0）。==", "（4）==关系表达式真时为1，假时为0==。", "（5）一般关系表达式会出现if 的条件、循环的条件等，经常与逻辑运算符构成复合表达式。", "例如：", "if(a<5&& b>10)", "for(i=0;i<10;i++)", "7、逻辑表达式", "（1）运算对象加逻辑运算符==(&&，||，！==)", "（2）逻辑表达式加分号构成逻辑表达式语句。", "（3）注意各逻辑运算符的规则。", "（4）==注意短路现象1: 当||连接两个运算对象时，第一个运算对象为真时，不再执行第二个表达式。==", "==例a++||b++，如果表达式a++的值非零，则表达式b++不再执行。==", "==（5）注意短路现象2：当&&连接两个运算对象时，第一个运算对象为假时，不再执行第二个表达式。==", "==例a++&&b++,如果表达式a++的值为零，则表达式b++不再执行。==", "（6）一般逻辑表达式和关系表达等联合（复合表达式）用于if、循环条件等。", "8、条件表达式", "（1）运算对象加条件运算符（==?:==）", "（2）一般格式：==表达式1？表达式2：表达式3==", "==（3）当表达式1 的值为真时，执行表达2，否则执行表达式3==；", "（4）条件表达式加分号构成条件表达式语句。例如：a=b>0?a+1:a-1;", "（5）条件表达式可以嵌套使用，不建议嵌套层数太多，不方便理解与阅读。例如：", "a=b>0?c>0?a+2:a+1:a-1;", "（6）表达式1?表达式2:表达式3；等价于if(表达式1){表达式2}else{表达式3}", "9、赋值表达式", "（1）运算对象加赋值运算符（==`+=`、`-=`、`*=`、`/=`、`%=`、`<<=`、`>>=`、`&=`、`^=`、`|=`==）", "（2）赋值表达式加分号构成赋值表达语句。", "（3）赋值表达式格式为：变量名=表达式，赋值运算符左边必须为变量，赋值运算是把赋值运算符右边表达式的值赋给左边变量。", "（4）==复合赋值运算符是将算术运算符或位运算符与赋值运算符组合在一起组成的运算符，掌握复合赋值表达式转化为赋值表达式的方法。如n+=100 可转化为n=n+100。==", "10、逗号表达式", "（1）运算对象加逗号运算符（`,`），可将多个表达式顺序连接构成一个新的表达式。", "（2）==求值规则==：==从左向右依次计算各子表达式的值，最后一个子表达式的值作为整个逗号表达式的值==（逗号运算符优先级最低）。", "（3）基础例题：`(3+5, 6+8)` 整个逗号表达式的值是 ==`14`==（即最后一个子表达式 `6+8` 的值）。", "（4）顺序副作用例题 1：`a = (a=3*5, a*4)` 的值是 ==`60`==：括号内先执行 `a=3*5` 得 `a=15`，再计算 `a*4=60`，整个逗号表达式值为 `60`，最终赋给 `a`（`a` 为 `60`）。", "（5）顺序副作用例题 2（2027 技能 P15 修订）：==`(d=3*5, d*4, d+5)` 最后的值为 `20`==：`d=3*5` 将 `d` 赋值为 `15`；第二项 `d*4` 计算 `15*4=60` 但==`d` 本身并未被重新赋值（`d` 仍为 `15`）==；最后执行 `d+5=15+5=20`，故整个逗号表达式值为 ==`20`==。", "（6）顺序副作用例题 3：`int a,b; a=2, b=5, b++, a+b` 的值：依次执行 `a=2`、`b=5` 后再 `b++`（`b` 变为 `6`），最后计算 `a+b = 2+6 = 8`，整个逗号表达式值为 ==`8`==。", "（7）^^赋值与逗号优先级易错例题^^：设 `int x=1, y=1, z;`，若执行 `z = x++, y++, ++y;`：x 自增前为 `1`（自增后 `x=2`），y 先后自增为 `2`、`3`，则==整个逗号表达式 `z = x++, y++, ++y` 的值为 `3`==；但特别注意 ==赋值运算符 `=` 的优先级高于逗号运算符 `,`==，该语句实际等价于 `(z = x++), (y++), (++y);`，因此变量 `z` 得到的是 `1`（若写为 `z = (x++, y++, ++y);` 则 `z` 得到 `3`）！", "11、按位运算表达式", "（1）运算对象加按位运算符（==&，~，^,|,<<,>>==）", "（2）按位运算表达加分号构成按位运算表达式语句。", "（3）注意各运算符运算规则", "12、自增自减运算表达式", "（1）变量和自增自减运算符（==++，--==）组合", "（2）自增自减运算表达式加分号构成自增自减运算表达式语句。例如：++i,j--,k++,--m 等；", "（3）注意变量前后问题", "（4）==++变量等价于 变量=变量+1；其他依此类推。==", "13、复合表达式", "（1）若干个运算表达式组合而成", "（2）复合表达加分号构成复合表达式语句", "（3）==考点会给出一个复合表达式语句或表达式，让计算出结果。==", "==（4）计算复合表达结果时，结合运算符的优先级来，以及运算符的运算规则，注意逻辑与和逻辑或的短路问题。==", "（5）例如：", "如果a=1,b=0,c=10;请问以下表达式运算结果是多少，a,b,c 的值分别是多少?", "`(!a && b++ || c - 10) >= 10` 解析：`()` 优先级高，优先计算括号内的表达式；`&&` 与 `||` 按从左到右规则运算并出现^^短路现象^^，因 `!a == 0`，故 `b++` 不用执行，`!a && b++` 结果为 `0`；随后继续计算 `c - 10` 得 `0`，故 `0 || 0` 结果为 `0`。", "`(!a && b++ || c - 10)` 的值为 `0`，`0 >= 10` 为假（假值为 `0`），因此整个表达式的值为 `0`；因 `b++` 被短路跳过，变量 `a`、`b`、`c` 的值均保持不变。", "14、==大小写字母的 ASCII 码差值==：==大写字母与小写字母的 ASCII 码值相差 32==。 例如 'A' 的 ASCII 码值为 65，'a' 为 97，因此大写字母加 32 可转换为对应的小写字母。", "15、^^自增自减在不同语境下的区别^^：^^自增、自减的前缀与后缀在以下情况中没有区别：^^", "- ^^在 for 语句的表达式 3 位置^^，++i 和 i++ 作用相同。", "- ^^作为独立的语句^^，如 i++; 和 ++i;，最终都是把 i 加 1。 在以下情况中区别明显：", "- ==函数传参==：^^fun(i++) 先传递 i 的原值^^，再自增；fun(++i) 先自增，再传递新值。", "- ==逗号表达式==：^^(1, 2, i++) 的值是 i 自增前的值^^；(1, 2, ++i) 的值是 i 自增后的值。 注意：i++ 的表达式值是自增前的值，但 i 本身已经加 1；++i 的表达式值和 i 都是自增后的值。"], "title": "", "ordered": false}, {"t": "table", "id": "s1-2-4-t1", "imp": "hard", "rows": [["\\(ab\\) 或 \\(a \\cdot b\\) 或 \\(a \\times b\\)", "`a * b`", "乘号 `*` 不可省略"], ["\\(a^2\\)", "`a * a`", "C 语言无幂运算符 `^`，不可写作 `a^2`"], ["\\(a^3\\)", "`a * a * a` 或 `pow(a, 3)`", "使用 `pow` 需 `#include <math.h>`"], ["\\(a \\div b\\) 或 \\(\\frac{a}{b}\\)", "`a / b` 或 `(double)a / b`", "两操作数均为整型时 `/` 做整除截断"], ["\\(\\sqrt{a^2 + b^2}\\)", "`sqrt(a * a + b * b)`", "使用 `sqrt` 需 `#include <math.h>`"], ["\\(\\frac{-b + \\sqrt{b^2 - 4ac}}{2a}\\)", "`(-b + sqrt(b * b - 4 * a * c)) / (2 * a)`", "分子、分母均须加圆括号，且根号内为 `4 * a * c`"], ["\\(\\frac{a + b}{2}h\\)", "`(a + b) * h / 2.0`", "避免 `a/2` 先整除"], ["\\(a \\le b\\) 与 \\(a \\ge b\\)", "`a <= b`、`a >= b`", "严格两字符关系运算符"], ["`'a'` \\(\\le ch \\le\\) `'z'`", "`'a' <= ch && ch <= 'z'`", "@@严禁连写 `'a'<=ch<='z'`，须用 `&&` 连接两关系式@@"]], "title": "14、常见数学表达式的 C 语言表示", "headers": ["数学表达式", "规范 C 语言表达式", "注意要点"]}, {"t": "code", "id": "s1-2-4-b4", "imp": "normal", "code": "#include <stdio.h>\n\nint main(void) {\n    int a = 6, x, y, z, d, b;\n    a += a -= a * a;\n    int r1 = (3 + 5, 6 + 8);            /* 14 */\n    int r2 = (a = 3 * 5, a * 4);        /* 60 */\n    int r3 = (d = 3 * 5, d * 4, d + 5); /* d 仍为 15，结果为 20 */\n    int r4 = (a = 2, b = 5, b++, a + b);/* 2 + 6 = 8 */\n    x = 1; y = 1;\n    int r5 = (z = x++, y++, ++y);       /* = 优先级高于 , : z=1, 逗号表达式值 r5=3 */\n    printf(\"r1=%d, r2=%d, r3=%d, d=%d, r4=%d, r5=%d, z=%d\\n\", r1, r2, r3, d, r4, r5, z);\n    return 0;\n}", "lang": "c", "title": "复合赋值与 2027 教材 P15 逗号表达式求值验证"}, {"t": "callout", "id": "s1-2-4-b5", "imp": "core", "kind": "tip", "text": "• 逗号表达式：`表达式1, 表达式2, ..., 表达式n`，==自左向右依次计算每一个子表达式，整个逗号表达式的最终值和最终类型由最后一个子表达式 n 决定==；\n• 复合赋值：`x += a` 等价于 `x = x + (a)`，注意右侧整个表达式会被视为一个不可分割的整体加括号计算。", "title": "考向复习提示：逗号表达式与复合赋值表达式求值规则"}, {"t": "callout", "id": "s1-2-4-b6", "imp": "core", "kind": "trap", "text": "连续赋值语句 `a = b = c = 5;` 是完全合法的（赋值运算符自右向左结合，依次赋值）；但必须注意：==赋值号左边必须是合法的“可修改左值”（具有确定内存地址的变量），绝对不能是常量或表达式（如 `5 = a;` 或 `a + b = 3;` 均属严重语法错误）==！", "title": "高频易错陷阱：连续赋值表达式与左值（L-value）限制"}]$p3b_246$::jsonb, '', $p3s_246$S1-2.4 C 语言表达式类型（赋值表达式，算术表达式，关系表达式，逻辑表达式，条件表达式，逗号表达式）和求值规则。
1、表达式：运算对象加运算符构成表达式例如：赋值运算符加运算对象构成赋值表达式；i+=1
2、表达式语句：表达式加分号构成表达式语句例如：赋值表达式加分号又可构成赋值语句；i+=1;
3、运算对象：运算对象可以是表达式、常量、变量例如：
表达式：a+b,a+a,a>b;
常量：100L、3.1415F;
变量：a,b,c,i,j；
4、C 语言表达式类型：算术表达式、关系表达式、逻辑表达式、条件表达式、赋值表达式、逗号表达式、其他表达式（按位运算表达式、复合表达式等）。
常量/变量与运算符组成常见 C 语言表达式类型体系（算术/关系/逻辑/条件/赋值/逗号表达式）
5、算术表达式
（1）运算对象加算术运算符(+-*/%)
（2）算术表达式加分号构成算术表达式语句。
（3）求余（%）运算要求运算对象只能为整型。
（4）除法（/）运算符两边运算对象都为整型时，运算结果也为整型即舍掉小数部分。
（5）注意优先级，类型转换（隐式与显示），常考点：
（3）和（4）
6、关系表达式
（1）运算对象加关系运算符（>,<,>=,<=,!=,）
（2）关系表达式加分号构成关系表达式语句。
（3）C 语言用非0 表示逻辑真（值为1），用0 表示逻辑假（值为0）。
（4）关系表达式真时为1，假时为0。
（5）一般关系表达式会出现if 的条件、循环的条件等，经常与逻辑运算符构成复合表达式。
例如：
if(a<5&& b>10)
for(i=0;i<10;i++)
7、逻辑表达式
（1）运算对象加逻辑运算符(&&，||，！)
（2）逻辑表达式加分号构成逻辑表达式语句。
（3）注意各逻辑运算符的规则。
（4）注意短路现象1: 当||连接两个运算对象时，第一个运算对象为真时，不再执行第二个表达式。
例a++||b++，如果表达式a++的值非零，则表达式b++不再执行。
（5）注意短路现象2：当&&连接两个运算对象时，第一个运算对象为假时，不再执行第二个表达式。
例a++&&b++,如果表达式a++的值为零，则表达式b++不再执行。
（6）一般逻辑表达式和关系表达等联合（复合表达式）用于if、循环条件等。
8、条件表达式
（1）运算对象加条件运算符（?:）
（2）一般格式：表达式1？表达式2：表达式3
（3）当表达式1 的值为真时，执行表达2，否则执行表达式3；
（4）条件表达式加分号构成条件表达式语句。例如：a=b>0?a+1:a-1;
（5）条件表达式可以嵌套使用，不建议嵌套层数太多，不方便理解与阅读。例如：
a=b>0?c>0?a+2:a+1:a-1;
（6）表达式1?表达式2:表达式3；等价于if(表达式1){表达式2}else{表达式3}
9、赋值表达式
（1）运算对象加赋值运算符（+=、-=、*=、/=、%=、<<=、>>=、&=、^=、|=）
（2）赋值表达式加分号构成赋值表达语句。
（3）赋值表达式格式为：变量名=表达式，赋值运算符左边必须为变量，赋值运算是把赋值运算符右边表达式的值赋给左边变量。
（4）复合赋值运算符是将算术运算符或位运算符与赋值运算符组合在一起组成的运算符，掌握复合赋值表达式转化为赋值表达式的方法。如n+=100 可转化为n=n+100。
10、逗号表达式
（1）运算对象加逗号运算符（,），可将多个表达式顺序连接构成一个新的表达式。
（2）求值规则：从左向右依次计算各子表达式的值，最后一个子表达式的值作为整个逗号表达式的值（逗号运算符优先级最低）。
（3）基础例题：(3+5, 6+8) 整个逗号表达式的值是 14（即最后一个子表达式 6+8 的值）。
（4）顺序副作用例题 1：a = (a=3*5, a*4) 的值是 60：括号内先执行 a=3*5 得 a=15，再计算 a*4=60，整个逗号表达式值为 60，最终赋给 a（a 为 60）。
（5）顺序副作用例题 2（2027 技能 P15 修订）：(d=3*5, d*4, d+5) 最后的值为 20：d=3*5 将 d 赋值为 15；第二项 d*4 计算 15*4=60 但d 本身并未被重新赋值（d 仍为 15）；最后执行 d+5=15+5=20，故整个逗号表达式值为 20。
（6）顺序副作用例题 3：int a,b; a=2, b=5, b++, a+b 的值：依次执行 a=2、b=5 后再 b++（b 变为 6），最后计算 a+b = 2+6 = 8，整个逗号表达式值为 8。
（7）赋值与逗号优先级易错例题：设 int x=1, y=1, z;，若执行 z = x++, y++, ++y;：x 自增前为 1（自增后 x=2），y 先后自增为 2、3，则整个逗号表达式 z = x++, y++, ++y 的值为 3；但特别注意 赋值运算符 = 的优先级高于逗号运算符 ,，该语句实际等价于 (z = x++), (y++), (++y);，因此变量 z 得到的是 1（若写为 z = (x++, y++, ++y); 则 z 得到 3）！
11、按位运算表达式
（1）运算对象加按位运算符（&，~，^,|,<<,>>）
（2）按位运算表达加分号构成按位运算表达式语句。
（3）注意各运算符运算规则
12、自增自减运算表达式
（1）变量和自增自减运算符（++，--）组合
（2）自增自减运算表达式加分号构成自增自减运算表达式语句。例如：++i,j--,k++,--m 等；
（3）注意变量前后问题
（4）++变量等价于 变量=变量+1；其他依此类推。
13、复合表达式
（1）若干个运算表达式组合而成
（2）复合表达加分号构成复合表达式语句
（3）考点会给出一个复合表达式语句或表达式，让计算出结果。
（4）计算复合表达结果时，结合运算符的优先级来，以及运算符的运算规则，注意逻辑与和逻辑或的短路问题。
（5）例如：
如果a=1,b=0,c=10;请问以下表达式运算结果是多少，a,b,c 的值分别是多少?
(!a && b++ || c - 10) >= 10 解析：() 优先级高，优先计算括号内的表达式；&& 与 || 按从左到右规则运算并出现短路现象，因 !a  0，故 b++ 不用执行，!a && b++ 结果为 0；随后继续计算 c - 10 得 0，故 0 || 0 结果为 0。
(!a && b++ || c - 10) 的值为 0，0 >= 10 为假（假值为 0），因此整个表达式的值为 0；因 b++ 被短路跳过，变量 a、b、c 的值均保持不变。
14、大小写字母的 ASCII 码差值：大写字母与小写字母的 ASCII 码值相差 32。 例如 'A' 的 ASCII 码值为 65，'a' 为 97，因此大写字母加 32 可转换为对应的小写字母。
15、自增自减在不同语境下的区别：自增、自减的前缀与后缀在以下情况中没有区别：
- 在 for 语句的表达式 3 位置，++i 和 i++ 作用相同。
- 作为独立的语句，如 i++; 和 ++i;，最终都是把 i 加 1。 在以下情况中区别明显：
- 函数传参：fun(i++) 先传递 i 的原值，再自增；fun(++i) 先自增，再传递新值。
- 逗号表达式：(1, 2, i++) 的值是 i 自增前的值；(1, 2, ++i) 的值是 i 自增后的值。 注意：i++ 的表达式值是自增前的值，但 i 本身已经加 1；++i 的表达式值和 i 都是自增后的值。
14、常见数学表达式的 C 语言表示
数学表达式 规范 C 语言表达式 注意要点
\(ab\) 或 \(a \cdot b\) 或 \(a \times b\) a * b 乘号 * 不可省略
\(a^2\) a * a C 语言无幂运算符 ^，不可写作 a^2
\(a^3\) a * a * a 或 pow(a, 3) 使用 pow 需 #include <math.h>
\(a \div b\) 或 \(\frac{a}{b}\) a / b 或 (double)a / b 两操作数均为整型时 / 做整除截断
\(\sqrt{a^2 + b^2}\) sqrt(a * a + b * b) 使用 sqrt 需 #include <math.h>
\(\frac{-b + \sqrt{b^2 - 4ac}}{2a}\) (-b + sqrt(b * b - 4 * a * c)) / (2 * a) 分子、分母均须加圆括号，且根号内为 4 * a * c
\(\frac{a + b}{2}h\) (a + b) * h / 2.0 避免 a/2 先整除
\(a \le b\) 与 \(a \ge b\) a <= b、a >= b 严格两字符关系运算符
'a' \(\le ch \le\) 'z' 'a' <= ch && ch <= 'z' 严禁连写 'a'<=ch<='z'，须用 && 连接两关系式
复合赋值与 2027 教材 P15 逗号表达式求值验证
#include <stdio.h>

int main(void) {
    int a = 6, x, y, z, d, b;
    a += a -= a * a;
    int r1 = (3 + 5, 6 + 8);            /* 14 */
    int r2 = (a = 3 * 5, a * 4);        /* 60 */
    int r3 = (d = 3 * 5, d * 4, d + 5); /* d 仍为 15，结果为 20 */
    int r4 = (a = 2, b = 5, b++, a + b);/* 2 + 6 = 8 */
    x = 1; y = 1;
    int r5 = (z = x++, y++, ++y);       /* = 优先级高于 , : z=1, 逗号表达式值 r5=3 */
    printf("r1=%d, r2=%d, r3=%d, d=%d, r4=%d, r5=%d, z=%d\n", r1, r2, r3, d, r4, r5, z);
    return 0;
}
考向复习提示：逗号表达式与复合赋值表达式求值规则
• 逗号表达式：表达式1, 表达式2, ..., 表达式n，自左向右依次计算每一个子表达式，整个逗号表达式的最终值和最终类型由最后一个子表达式 n 决定；
• 复合赋值：x += a 等价于 x = x + (a)，注意右侧整个表达式会被视为一个不可分割的整体加括号计算。
高频易错陷阱：连续赋值表达式与左值（L-value）限制
连续赋值语句 a = b = c = 5; 是完全合法的（赋值运算符自右向左结合，依次赋值）；但必须注意：赋值号左边必须是合法的“可修改左值”（具有确定内存地址的变量），绝对不能是常量或表达式（如 5 = a; 或 a + b = 3; 均属严重语法错误）！$p3s_246$, $p3r_246${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S1-2.4 C 语言表达式类型（赋值表达式，算术表达式，关系表达式，逻辑表达式，条件表达式，逗号表达式）和求值规则。", "题库补充：大小写字母的 ASCII 码差值 (13题)", "题库补充：自增自减在不同语境下的区别 (7题)", "2024智狐《操作技能》补充：常见数学表达式的C语言表示对照表，及错别字/高亮标记修复", "p1_refine_20261114", "p3_zhihu27_20261114"], "pages": [22, 23, 24, 25], "spans": 42}$p3r_246$::jsonb, NOW());
