-- 提交前数据库级完整性校验（CR 残留、8 个版本、新旧资产引用完整性）
DO $$
DECLARE
  v_cr_cnt INT;
  v_p3_cnt INT;
  v_old_asset INT;
  v_new_asset INT;
  v_old_ref INT;
  v_new_ref INT;
BEGIN
  SELECT count(*) INTO v_cr_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.search_text LIKE '%' || E'\r' || '%';
  IF v_cr_cnt > 0 THEN
    RAISE EXCEPTION 'Found % published nodes with CR in search_text', v_cr_cnt;
  END IF;

  SELECT count(*) INTO v_p3_cnt
    FROM kb_entry
   WHERE status = 'published' AND ((node_id = 51 AND published_rev = 12) OR (node_id = 112 AND published_rev = 5) OR (node_id = 126 AND published_rev = 5) OR (node_id = 205 AND published_rev = 5) OR (node_id = 246 AND published_rev = 5) OR (node_id = 249 AND published_rev = 5) OR (node_id = 260 AND published_rev = 5) OR (node_id = 263 AND published_rev = 4));
  IF v_p3_cnt <> 8 THEN
    RAISE EXCEPTION 'Expected 8 updated P3 nodes, got %', v_p3_cnt;
  END IF;

  SELECT count(*) INTO v_old_asset FROM kb_asset WHERE path = '/kb-assets/skill/p46_r0_a1ae508d9e594341.png';
  IF v_old_asset <> 0 THEN
    RAISE EXCEPTION 'Obsolete asset still present in kb_asset: %', v_old_asset;
  END IF;

  SELECT count(*) INTO v_new_asset FROM kb_asset WHERE path = '/kb-assets/refinement/s164-selection-sort.png';
  IF v_new_asset <> 1 THEN
    RAISE EXCEPTION 'New asset missing or duplicated in kb_asset: %', v_new_asset;
  END IF;

  SELECT count(*) INTO v_old_ref
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.blocks::text LIKE '%' || '/kb-assets/skill/p46_r0_a1ae508d9e594341.png' || '%';
  IF v_old_ref <> 0 THEN
    RAISE EXCEPTION 'Published revision still references obsolete image: %', v_old_ref;
  END IF;

  SELECT count(*) INTO v_new_ref
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.blocks::text LIKE '%' || '/kb-assets/refinement/s164-selection-sort.png' || '%';
  IF v_new_ref <> 1 THEN
    RAISE EXCEPTION 'Expected 1 published revision referencing new image, got %', v_new_ref;
  END IF;
END $$;

COMMIT;
